using System.Buffers.Text;
using System.Security.Cryptography;
using System.Text;

namespace ValkyrieID.Core.Security;

/// <summary>
/// Generates and verifies client and API resource secrets. The secrets are 256-bit random values
/// generated by the server, so a fast hash (SHA-256) is sufficient; user-chosen passwords must use
/// Argon2id instead.
/// </summary>
public static class SecretHasher
{
    public const int SecretSizeBytes = 32;

    /// <summary>Hash compared against when the client is unknown, so the work done stays constant.</summary>
    private static readonly byte[] DummyHash = SHA256.HashData(RandomNumberGenerator.GetBytes(SecretSizeBytes));

    /// <summary>Generates a new base64url-encoded secret.</summary>
    public static string Generate() => Base64Url.EncodeToString(RandomNumberGenerator.GetBytes(SecretSizeBytes));

    public static byte[] Hash(string secret) => SHA256.HashData(Encoding.UTF8.GetBytes(secret));

    /// <summary>
    /// Returns whether <paramref name="secret"/> matches any of <paramref name="hashes"/>. Every hash is
    /// compared in constant time; with no hashes a dummy comparison is still performed.
    /// </summary>
    public static bool Verify(string secret, IEnumerable<byte[]> hashes)
    {
        var candidate = Hash(secret);
        var match = false;
        var compared = false;
        foreach (var hash in hashes)
        {
            compared = true;
            match |= CryptographicOperations.FixedTimeEquals(candidate, hash);
        }

        if (!compared)
        {
            _ = CryptographicOperations.FixedTimeEquals(candidate, DummyHash);
        }

        return match;
    }
}
